package com.practiq.web; import com.practiq.common.*; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/health") public class HealthController {final JdbcTemplate db;final StringRedisTemplate redis;final long started=System.currentTimeMillis();public HealthController(JdbcTemplate d,StringRedisTemplate r){db=d;redis=r;} @GetMapping ResponseEntity<ApiResponse<?>> health(){return response(state(),200);}@GetMapping("/live")ResponseEntity<ApiResponse<?>> live(){return response(Map.of("ok",true,"uptimeSeconds",(System.currentTimeMillis()-started)/1000),200);}@GetMapping("/ready")ResponseEntity<ApiResponse<?>> ready(){var x=state();return response(x,Boolean.TRUE.equals(x.get("ok"))?200:503);}private ResponseEntity<ApiResponse<?>> response(Map<String,Object>x,int s){return ResponseEntity.status(s).header(HttpHeaders.CACHE_CONTROL,"no-store").body(ApiResponse.ok(x));}private Map<String,Object> state(){long a=System.nanoTime();boolean pg=false,rd=false;try{db.queryForObject("select 1",Integer.class);pg=true;}catch(Exception ignored){}double p=(System.nanoTime()-a)/1e6;a=System.nanoTime();try{redis.hasKey("practiq:health");rd=true;}catch(Exception ignored){}double r=(System.nanoTime()-a)/1e6;return Map.of("ok",pg&&rd,"uptimeSeconds",(System.currentTimeMillis()-started)/1000,"latencyMs",Math.max(p,r),"services",Map.of("postgres",Map.of("ok",pg,"latencyMs",p),"redis",Map.of("configured",true,"ok",rd,"latencyMs",r)));}}
